//	Kp 205 恰好合适：0.2 PWM 每 0.1cm = 2 PWM/cm —— 高度误差 10cm ⇒ 20 PWM，
//	与旧"外环P+内环P"串级的等效增益(10cm→5cm/S→10PWM)同量级、略紧一点。
//	Ki 1：err 5cm(50) 时积分速率 = 50×200/1024 ≈ 10 PWM/S，温和。
//	KD 10→50：D 现在作用在速度差分(0.1cm/S/拍)上，50 ⇒ 100cm/S² 垂向加速度
//	产生 ~24 PWM 阻尼，补上删除速度环后丢失的阻尼——单环必备，否则气压
//	滞后会引起高度环慢振荡。
//==================================================================================
#define FC_VZ_KP_Q10		205			// 0.20 → 高度误差 10cm(100) ⇒ 20PWM
#define FC_VZ_KI_Q10		1			// 0.001：err 5cm ⇒ ~10PWM/S 积分速率
#define FC_VZ_KD_Q10		50			// 0.05（v19 由 10 提高：速度差分=加速度阻尼）
// ★ 2026/11/07 第五轮：积分权限 30~360 → 70~260。
//	台架快照 Thrust=400(顶死)、VzCmd=0、VzX10=+18.6 三者同时出现，唯一解释是
//	【积分已顶在最大值、环事实上处于开环满推力】。而 Ki=0.001 每拍只泄 0.18PWM，
//	从 400 泄到悬停要 2 秒以上 —— 于是：满推力猛爬(2S) → 泄到悬停 → 掉高度
//	→ 再爬。这就是"脉冲"的周期来源（限推力 340 后只是幅度小一点，周期不变）。
//	把上限定在 260(悬停+90) 后，即使积分饱和，最大推力也只有 260，
//	爬升速度天然被限制在合理范围；下限 70 保证降得下来。
// ★v27 复查：FC_PWM_HOVER 改成 250 后，(hover+90)=340 正好等于 FC_THR_MAX_CMD，
//	积分单独就能把推力顶到指令上限、P 项再无向上权限（饱和时环退化为开环）。
//	故上限改 hover+70 = 320，永远留 20PWM 的 P 权限；下限 hover-100 = 150
//	（远低于悬停即可压住高度，不需要更低）。
// ★v28 复查：FC_THR_MAX_CMD 340→290 后，320 又超过指令上限了（同一坑）。
//	同步压到 hover+40 = 290 = FC_THR_MAX_CMD，P 权限恢复 ≥0；下限不变 150。
#define FC_VZ_I_MIN			((FC_PWM_HOVER-100)<<10)	// 积分限幅下限(150PWM@hover250)
#define FC_VZ_I_MAX			((FC_PWM_HOVER+40)<<10)		// 积分限幅上限(290PWM@hover250)
#define FC_VZ_OUT_MIN		0
#define FC_VZ_OUT_MAX		FC_PWM_MAX

