//==================================================================================
// 7.4 高度/升降速度估计：气压 + 加速度互补融合（2026/11/04 新增，★治本）
//----------------------------------------------------------------------------------
// ★ 真机复测结论（2026/11/04 第一轮）：脉冲爬升依旧、实际爬升速度超过目标速度。
//	根因：气压高度被桨流"劫持"——推力增大 → 下洗/动压增强 → 气压读数升高
//	→ 表观高度下降（支架实测 -7.1cm、贴地 -54.6cm，且随推力变化）。
//	正反馈链：爬升脉冲 → 推力↑ → 表观高度↓ → 高度/速度环以为"没爬够"
//	→ 加推力 → 爬升远超目标 → 又一个脉冲。调增益/限推力都治不了本。
//
// ★ 2026/11/04 第二轮（加计融合）台架实锤：飞机静止、马达满转时
//	AltX10 = -9.1cm、VzX10 = VzBaroX10 = -4.0cm/S —— 静止的飞机被估成
//	"正在以 4cm/S 下降"。加计通道本身是好的（静止时 vz_acc≈0），但上一版把
//	气压纠漂的时间常数设成 τ≈0.25S/0.5S，比桨流偏置的建立过程(0.5~2S)还快，
//	等于气压照样说了算 → 正反馈原封不动，只是幅度小一点。
//
// ★ 第三轮（本版）三条修正，缺一不可：
//	① 纠漂必须真的"慢"：速度 τ≈4S、高度 τ≈8S，远离桨流偏置的时间尺度，
//	   这样气压无论如何变化都进不了控制环的带宽里；
//	② 纠漂门控：推力一动就冻结气压纠漂（桨流偏置只在推力变化时突变）；
//	③ 用 Q8 累加器做纠漂，避免 >>N 把小误差截断成 0（小误差永远修不动）。
//
// ★ 若日后换机型/加装海绵罩，可先看 BDT：飞机静止、马达满转时
//	VzAccX10 应≈0 且 VzX10 不再跟随 VzBaroX10 跳动。
//==================================================================================
// ★ 2026/11/07 第五轮台架实锤（飞机被固定在支架上、马达 400）：
//	AVert=+298(0.03g)、VzAccX10=+18.6cm/S、VzBaroX10=-2.2cm/S。
//	真实速度恒为 0，说明【加计快通道比气压差 8 倍】——桨流/机体振动对 MEMS 加计
//	的整流效应（振动被"整流"成直流偏置，低通滤不掉）把垂向加计变成了推力的函数：
//	推力↑ → a_vert↑ → vz_acc↑ → 环判"升太快" → 减推力 → a_vert↓ → 判"没升" → 加推力
//	→ 这是一个【正反馈弛张振荡器】，振荡周期由积分器/限幅决定 = 脉冲爬升。
//	结论：本机的垂向加计不能当作速度主通道。故关闭融合，回到纯气压（误差小 8 倍）。
// ★ 2026/11/09 v16 重启融合：当时融合失效的真正原因是【振荡把推力打得一直变化
//	→ 纠漂门 corr_open 永远关着 → 加计零偏漂移无界 → 饱和致盲】。v13 后振荡已灭、
//	推力平稳，纠漂门能正常开合；且本机零偏已有上锁学习（7.5）。融合按用户需求分
//	工：起飞/短时急剧变化以加计为准（桨流骗不了它），持续缓慢变化以气压为准。
//	另加纠漂防抖：推力须连续稳定 FC_VZ_CORR_DEBOUNCE 拍才引入气压（等"气压稳定"）。
// ★ 2026/11/09 v18 关闭（第18轮 v17 自由飞实锤）：
//	① 1Hz 翼摆消失后仍持续爬升，且【向下拉油门杆也无法降低爬升速度】。
//	② 唯一能同时解释两条的机制：加计快通道在真实飞行中被振动整流污染成
//	  假"下降"（vz_acc 负向饱和 -30cm/s）：
//	    拉杆 vz_cmd=-12cm/s → err = -120 - (-150) = +30 仍为正
//	    → 推力压不下来 → 拉杆无效、持续爬升（与实测逐字吻合）；
//	  同时 alt_fast 按假速度向下积分，飞机实际在爬、估计高度却"在降"
//	    → 高度环以为没到目标 → 继续命令爬升。
//	  气压纠漂限幅 ±15cm/s、τ≈4S，救不回 30cm/s 的假速度。
//	③ 第5轮台架早有前科：推力400 时 a_vert=+298、vz_acc=+18.6cm/S（振动整流
//	  是推力的函数），当时因此关过融合；v16 重启的理论前提（推力平稳）在
//	  自由飞中不成立——漂移+爬升本身就在改变推力。
//	★ 本轮按用户试验方案：彻底切断加计快通道，纯气压定高——起飞2S后
//	（离地静默窗口，见 FC_LIFT_QUIET）重清气压基准并把高度直接锁定在
//	气压读数上。悬停时推力恒定→桨流偏置恒定→气压高度锁住=真实高度锁住。
//	代价：推油门/拉杆瞬间气压偏置突变会有短暂高度扰动（稳态后收敛）。
// ★ 2026/11/10 v19（按用户判定）：主飞行保持纯气压（加计快通道仍关闭）；
//	加计积分仅保留【离地静默窗口】内做垂直速度PID（见 FC_LIFT_QUIET），
//	窗口结束即切回气压。v18 的"冻结推力"做法取消。
#define FC_VZ_ACC_FUSE_EN	0			// 0: 主飞行纯气压（v19：加计仅用于离地窗口速度环）

// 纠漂速率（每气压拍 15.6mS 的 err>>SHIFT）：τ = 2^SHIFT × 15.6mS
#define FC_VZ_CORR_SHIFT	8			// 速度纠漂 τ≈4S（原 4 = 0.25S，太快=没融合）
#define FC_ALT_CORR_SHIFT	9			// 高度纠漂 τ≈8S（原 5 = 0.5S）
#define FC_VZ_CORR_GATE		12			// 推力指令与慢速推力相差 > 1.2% 满量程 → 冻结纠漂
										// (PWM；台架实测推力阶跃是桨流偏置的唯一来源)
#define FC_VZ_CORR_DEBOUNCE	400			// ★v16: 推力须连续稳定 400拍(2S) 才开纠漂
										// （= 用户要求"起飞成功、气压稳定后才引入气压"）
#define FC_VZ_ACC_LIMIT		300			// 加计快通道速度限幅 ±30cm/S（原 ±50：饱和越深，
										// 估计越盲、环越像开环，压到 30cm/S 已够本机用）
#define FC_VZ_CORR_LIMIT	150			// 气压纠漂量限幅 ±15cm/S（原 ±30：纠漂也是桨流
										// 污染进入速度环的唯一通道，权限必须收紧）
#define FC_VZ_EST_LIMIT		300			// 融合速度输出限幅 ±30cm/S
#define FC_ALT_CORR_LIMIT	5000		// 气压纠高量限幅 ±500cm

//----------------------------------------------------------------------------------
// 7.5 垂向加速度零偏标定（2026/11/06 新增，★治"脉冲爬升"的真正根因）
//----------------------------------------------------------------------------------
// ★ 根因（2026/11/06 第四轮复盘确认）：
//	fc_vert_accel_01() 减掉的重力 9810 是【理想值】，而 ICM42670 的零偏规格
//	±40~50mg（≈±400~500 × 0.1cm/S²），传感器真实零偏从未扣除 → a_vert 带恒定偏差。
//	后果链：vz_acc_q 每 5mS 积分 a_vert_lpf，零偏 -400 时每秒漂 -40cm/S，
//	1~2 秒就把 vz_acc 推到 -50cm/S 限幅；且 vz_acc_q 本身【不钳位】，
//	越灌越深、永远出不来 → 速度环永远以为"在高速下降"
//	→ err = vz_cmd-(-500) 恒为正 → 推力顶死 FC_THR_MAX_CMD
//	→ 失控快速爬升（宏观即"脉冲爬升"），与指令速度完全无关。
//	这一根因解释全部实测现象：
//	  ① FC_ALT_LOOP_EN=0（vz_cmd 恒 0）依旧脉冲 —— err 还是 +500；
//	  ② 爬升远超目标速度 —— 估计器已饱和致盲，环呈开环满推力；
//	  ③ 调气压融合/门控/KI 全部无效 —— 快通道自己已坏；
//	  ④ 台架发现不了 —— 静止 |a_vert|<500 不误触离地，且 VzAccX10 从未抓取。
//	对策：上锁状态（马达停转、机体静止）持续学习 a_vert 零偏存入 a_vert_bias，
//	解锁后冻结使用；a_vert_lpf 一律用【扣除零偏后的净值】。
//	注意：上电后请静置 ≥2S 再解锁，让零偏先收敛。
//----------------------------------------------------------------------------------
#define FC_ACC_BIAS_EN		1			// 1: 上锁时自动学习垂向加速度零偏
#define FC_ACC_BIAS_SHIFT	8			// 学习速率 >>8，τ≈1.3S（马达停转时才学习）
// ★ 2026/11/07：门限 300→2500。原门限 300 与实测偏置同量级（298），
//	只要真实偏置略超 300 学习就永远被挡住 → AccBiasX10 恒 0（本轮实测正是如此）。
//	学习本身是"静止时慢慢收敛"，门限只需挡住搬动/晃动，2500(2.5m/S²) 足够。
#define FC_ACC_BIAS_GATE	2500		// |a_vert|>2500 视为搬动/晃动，暂停学习

//==================================================================================
// 7.6 垂直轴控制模式（2026/11/07 第五轮新增，★本轮默认走手动）
//----------------------------------------------------------------------------------
// ★ 为什么要有这一节：
//	四轮修改全部失败的共同点是——垂直轴是【闭环】，而它的反馈（气压/加计）
//	在这台机器上都是推力的函数：
//		气压：推力↑ → 表观高度↓（支架 -7cm、贴地 -55cm）
//		加计：推力↑ → 振动整流偏置↑（本轮实测 +18.6cm/S @推力400）
//	只要是闭环，反馈一被推力"劫持"，环就会自己制造振荡；而且一旦积分饱和，
//	环事实上变成"开环满推力"，这时【你设的 12cm/S 目标速度根本不起作用】——
//	这正是"目标速度很小、实测爬升很快"的原因：指令只管误差，推力由积分决定。
//
// ★ 本轮策略：把垂直轴改成【手动油门直驱】（等价于固定翼/穿越机的自稳模式）
//	thrust = FC_MAN_THR_MID + 杆量 × FC_MAN_THR_SPAN
//	没有任何速度反馈 → 不可能自激；杆位直接决定推力，推力决定爬升率。
//	这样做的另一个价值是【二分】：若手动模式下不再脉冲、姿态也稳，就证明
//	机架/桨/混控/姿态环都没问题，剩下的只是"垂直传感器不可用"这一个问题。
//
// ★ 后续再上定高：先用手动模式把真实悬停推力测出来（BDT 看 Thrust 稳定值），
//	把 FC_PWM_HOVER 改成实测值，再 FC_VZ_MANUAL_EN=0 回首闭环。
//==================================================================================
// ★ v17 已切回闭环（FC_VZ_MANUAL_EN=0），本节保留作诊断/二分回退：
//	把本宏改回 1 即可恢复手动直驱。★ 16 轮实测教训（v17 修复依据）：
//	手动模式下 fc_ground_detect 的"降不下去"判据不成立——目标高度独立下坠、
//	飞机跟杆走，拉杆下降 0.5S 后"目标低于实际 6cm"即成立，加上推力突降时
//	桨流偏置释放把估计高度托住不降 → 1S 窗口判"已落住"→ 拉油门即停桨
//	（用户实测"向下拉油门立刻停飞"的 Bug）。手动模式的落地判定已改为
//	专用判据（见 FC_MAN_LAND_*），仅手动模式编译。
#define FC_VZ_MANUAL_EN		0			// 1: 垂直轴手动油门直驱（诊断用）
										// 0: 恢复 速度环 → 高度环 闭环定高（v17）
#define FC_MAN_THR_MID		190			// 杆回中时的推力(PWM)，应≈实测悬停推力
										// v14: 实测悬停在"释放后微降一点"≈190（原200偏爬升）
#define FC_MAN_THR_SPAN		140			// 满杆行程对应的推力增量 ±140PWM
										// → 杆位范围 60 ~ 340（FC_THR_MAX_CMD）
// ★ v16 垂直速度阻尼（配合 7.4 融合重启）：手动油门不再是纯开环——
//	thrust -= K·vz_est，松杆≈垂直速度保持。慢爬升/慢下降被自动压住，
//	（加计快通道反应快，气压只负责慢慢消零偏），杆量仍保留主导权（限幅小）。
#define FC_MAN_VZ_DAMP_EN	1			// 1: 手动油门叠加垂直速度阻尼
#define FC_MAN_VZ_GAIN_Q8	9			// 阻尼增益：20cm/S 爬升 ≈ 减 7 PWM
#define FC_MAN_VZ_LIMIT		30			// 阻尼输出限幅 ±30 PWM（杆量永远占主导）

// ★ 2026/11/07 真机实测（手动模式）：自由飞行中拉油门杆【降不下来】，一直上飞。
//   机理解密：姿态环 2~3Hz 摆动 → 差动量大（限幅 ±180×1.41≈±254 PWM）→ 混控
//   在下限 45 处削顶：m_low = 60-254 → 抬回 45，m_high = 60+254 = 314 不削
//   → 平均推力 = (45+314)/2 ≈ 180 ≈ 悬停推力！杆位给的 60 被"削顶"偷偷抬回
//   悬停 → 拉杆无效、持续上飞；摆动幅度起伏调制平均推力 = 脉冲感。
//   对策：差动权限随推力收缩，保证 m_min 永不触底 → 平均推力≡杆位指令。
#define FC_DIFF_ROOM_MAX	160			// 单轴差动幅度上限(PWM，混控后)

//----------------------------------------------------------------------------------
// ★ v17 手动模式专用落地判定（仅 FC_VZ_MANUAL_EN=1 时编译）：
//	手动直驱没有"目标高度"跟随，fc_ground_detect 的判据必然误触发（见上）。
//	改为直接判物理状态：油门杆持续拉低 + 估计垂速≈0 + 垂向加速度≈0，
//	持续 FC_MAN_LAND_TMOUT → 判定已落住。空中不可能同时满足三条
//	（杆拉低时推力≈97 PWM，远低于悬停，飞机必在下降），只有真落地才满足。
//----------------------------------------------------------------------------------
#define FC_MAN_LAND_THR		8			// 油门杆拉低超过 -8cm/S（约 2/3 行程）
#define FC_MAN_LAND_VZ		20			// |估计垂速| < 2.0cm/S（已停止升降）
#define FC_MAN_LAND_ACC		400			// |垂向加速度| < 40cm/S²（无升降动态）
#define FC_MAN_LAND_TMOUT	300			// 三条件连续满足 300×5mS = 1.5S → 判定落地

//----------------------------------------------------------------------------------
// 7.7 悬停漂移自学习（2026/11/07 新增，回答"能否用加速度判断并纠正漂移"）
// ★ v16 改架构：改为【吸收 7.10 漂移阻尼器的稳态输出】。
//	原 v15 直接闭环在 ax/ay 上，与阻尼器（也闭环在加速度上）形成双积分环路，
//	相位滞后叠加 → 实测 1Hz/±10° 翼摆极限环。现在：阻尼器（快，τ≈1.3S）负责
//	把漂移刹住并保持一个反倾角；自学习（慢，0.1°/S）把阻尼器的输出慢慢"接管"过来，
//	使阻尼器输出回到 0。单通道串级结构，无环路互拍；翼摆由阻尼器额外提供阻尼。
//----------------------------------------------------------------------------------
#define FC_HTRIM_EN			1			// 1: 启用悬停漂移自学习（手测可用后保持）
#define FC_HTRIM_LP_SHIFT	8			// ax/ay 平滑 >>8，τ≈1.3S（滤桨流振动，兼作门限源）
// ★ v18 吸收提速：原 0.1°/S 吸收 2° 要 20S，漂移早已跑远（v17 左上快漂期间
//	配平根本来不及接管）。现 0.1°/0.25S = 0.4°/S，4 倍提速；总量限幅 4°→6°
//	（桨平面装配倾角可能 >4°）。仍远慢于阻尼器响应（τ≈1.3S），串级无互拍。
#define FC_HTRIM_PERIOD		50			// 每 50 拍(0.25S)调整一次配平（v18 由 100 提速）
#define FC_HTRIM_DIV		10			// Δtrim = 阻尼输出/10（v18 由 20 提速）
#define FC_HTRIM_STEP		10			// 单次调整限幅 ±0.1°（v18 由 0.05° 提速）
#define FC_HTRIM_LIMIT		600			// 自学习配平总量限幅 ±6.0°（v18 由 ±4° 放宽）
#define FC_HTRIM_RATE_GATE	100			// |角速度|<10°/S 才学习（机动/摆动中冻结）
#define FC_HTRIM_ACC_GATE	6000		// |ax/ay|<6m/S² 才学习（异常机动/碰撞保护）
#define FC_HTRIM_THR_MIN	120			// 推力 120~320 之间才学习（悬停附近）
#define FC_HTRIM_THR_MAX	320

//----------------------------------------------------------------------------------
// 7.10 水平速度估计 + 漂移阻尼（2026/11/09 新增，v16 核心特性）
//----------------------------------------------------------------------------------
// 用户需求：飞行器快速漂移时玩家来不及微调，要求程序自动抑制。
// 用户洞察：漂移的根源是【桨平面】相对水平面有倾角（机械装配误差），而姿态估计
//	只反映 PCBA 姿态——两者不重合，靠"估计角"修漂移修不到根上。
// 实现思路（比"推力扰动辨识"更连续）：不用倾角假设，直接闭环在【漂移本身】上——
//	水平加速度 = 加计水平分量 − 重力投影(g·sin估计角)。桨平面歪了 → 机体被加速
//	→ 加计直接感测到（无论倾角来自 PCB 还是桨平面）→ 积分成速度 → 反打姿态角
//	刹停。泄漏积分(τ≈1.3S)防加计偏置无限积累；杆量>1° 时冻结积分（不抗玩家指令）。
//	输出限幅 ±2°，只会"刹漂移"，不会抢操控。稳态反倾角由 7.7 自学习慢速接管。
// ★ v18 阻尼器增强（第18轮 v17 实测"左上快漂未抑制"的对策）：
//	v17 修翼摆把 roll 外环 450→100，阻尼器 ±2° 输出经外环产生的姿态修正
//	力度同步被削弱 4.5 倍（2° 误差→2°/S 而非 8.8°/S），漂移加速度赢过阻尼器。
//	不动外环（保住翼摆已消失的成果），改在本级增强：
//	  增益 100→150（50cm/S → 反打 2.9°）、输出限幅 ±2°→±3°；
//	并加快自学习吸收（见 FC_HTRIM_*），稳态反倾角更快移交配平。
//	环稳定裕度评估：v16 阻尼环路总增益 ≈ 1.0×4.5=4.5（相对单位），v18 ≈ 1.5×1.0=1.5，
//	仍远低于 v16（当时无阻尼自激），且泄漏 τ1.3S 提供相位裕度。
#define FC_HVEL_EN			1			// 1: 启用水平速度阻尼
#define FC_HVEL_LP_SHIFT	5			// 水平加速度低通 >>5，τ≈160mS（滤振动）
#define FC_HVEL_LEAK_SHIFT	8			// 速度泄漏 >>8/拍，τ≈1.28S（限偏置积累）
#define FC_HVEL_GAIN_Q8		150			// 阻尼增益：速度 50cm/S → 反打 2.9°（v18 由 100 增强）
#define FC_HVEL_TGT_LIMIT	300			// 阻尼输出限幅 ±3.0°（v18 由 ±2° 增强）
#define FC_HVEL_V_LIMIT		1000		// 速度估计限幅 ±100cm/S
#define FC_HVEL_STICK_GATE	100			// |目标角|>1°(机动中) 冻结积分并快速泄放

//----------------------------------------------------------------------------------
// 7.9 UART 高速调试报文（2026/11/07 新增，治 pitch 点头的取证工具）
//----------------------------------------------------------------------------------
// ★ 2026/11/08：帧尾新增 1 字节参数版本 FC_PARAM_VER——每轮改参数必须 +1，
//	解析脚本会打印它，用于从数据端证明"烧的确实是新固件"（本轮实测发现
//	新 bin 尺寸与旧 bin 同为 33540 字节，烧录混淆导致改参无效）。
#define FC_PARAM_VER		34			// 第34版: ①气压高度修复：alt_target 下限 -20m→-10cm
										//   （V32_2/V33_1 杆下拉把目标滑到 -5~-7cm 地下，
										//   高度环忠实执行→贴地湍流翻机）；地面斜坡阶段
										//   继续学习 a_vert_bias（吸收悬停推力振动整流
										//   偏置，治 vz_acc 恒 -30cm/s 导致高度估计偏小）；
										//   离地瞬间清 vz_acc_q/vz_corr_q 甩掉斜坡垃圾
										//   ②roll 1.3Hz 极限环：外环 Kp 100→200（对齐
										//   pitch）、内环 Ki 12→6、Kd 10→20（用户方案）
										//   ③黑匣子 38→42B：加 roll/pitch 原始角速度两列
										//   （贴墙等极端工况区分真实旋转与估计迟钝）
//
// 每个控制节拍(5mS → 200Hz)发送 1 包 21 字节，115200-8-N1（占用带宽 ~37%）。
// 串口工具按 HEX 录原始字节 → 用配套 python 脚本解析。
//
//  偏移  内容（★v16 起 7~8、15~16、17~18 通道换成速度估计；ver<16 为旧定义）
//   0    0x26  帧头1
//   1    0x99  帧头2
//   2    seq   包序号 u8（0~255 循环，检测丢帧/对时间轴）
//   3~4  pitch_meas     s16 大端  姿态估计 pitch（0.01°，含符号宏）
//   5~6  rate_y         s16 大端  pitch 角速度测量（0.1°/S，陀螺+符号宏）
//   7~8  vel_x          s16 大端  水平速度估计 x（0.1cm/S）——v16: 原 pitch_rate_cmd
//   9~10 out_p          s16 大端  pitch 角速度环输出（PWM）
//  11~12 roll_meas      s16 大端  姿态估计 roll（0.01°）——v15: 原 diff_p（诊断横向漂移）
//  13~14 thrust         s16 大端  总推力（PWM）
//  15~16 vel_y          s16 大端  水平速度估计 y（0.1cm/S）——v16: 原 rate_x
//  17~18 vel_z          s16 大端  垂直速度估计（0.1cm/S，融合输出）——v16: 原 htrim_pack
//  19    ver            u8 = FC_PARAM_VER（参数版本，验证烧录）
//  20    chk            u8 = sum(byte[2..19])
//
// 停机(DISARM)状态下各数据通道发 0（作为马达停转的噪声基线）。
// ★ 分析判据：
//   - pitch_meas 振荡而 rate_y 的积分对不上 → 角度估计被加计/振动污染
//   - rate_y 本身有 2~3Hz 相干振荡 → 真实运动（环路增益/执行器问题）
//   - rate_y 只有宽谱噪声、无相干振荡而 out_p 仍振 → 振动整流激励环路
//   - out_p 频繁贴 ±150 或 diff_p 贴 ±room → 限幅饱和（权限不足）
//   - out_p 与 out_r 幅度对比 → 确认 pitch 轴特异性
// 注意：usart1_report_EulerDat() 与本报文共用 UART TX 缓冲/DMA，录本
//       报文期间请勿同时打开 Euler 报文，否则互相丢帧。
//----------------------------------------------------------------------------------
#ifndef FC_UART_DBG_EN
#define FC_UART_DBG_EN		0			// ★v26: 1→0。实时调试帧每 5mS 21B（@115200 占
										//   节拍带宽 ~37%），会让黑匣子 UART 读出流混入
										//   无关报文、parse_fcbb.py 无法干净解析。
										//   需要实时遥测时改回 1（此时先别读出黑匣子）。
#endif


//----------------------------------------------------------------------------------
// 7.11 flash 黑匣子（v20 引入；v24 曾因 RAM 溢出整体删除；★v26 修复"录不上"）
//----------------------------------------------------------------------------------
// 历史教训：本芯片栈顶 = 0x842000（cstartup_flash.S），可用 RAM 仅 8KB；v20 版
//   黑匣子占 ~500B 静态 RAM（bb_wbuf[256] + T_txdata_user 36→252B）压垮栈，
//   把 .bss 末尾的 u16*_Rxd / UserRfRcvBuffer 踩乱 → 无法解锁（v20~v23 同因）。
// ★v25 精简设计（静态 RAM 仅 ~24B）：
//   ① 无 256B 页写缓冲——每条记录(38B)单独 flash_write_page（50Hz，每次阻塞
//      约 0.3mS，远小于擦除的 30~100mS）；
//   ② 记录/区域头在栈上临时组包，不占静态 RAM；
//   ③ 读出直读直发：flash_read_page → T_txdata_user.data（复用调试帧 40B 缓冲）
//      → UART DMA，32B/块阻塞发送，不新增缓冲。
// ★v26 修复"试飞后 BDT 抽查录制区全是 0"：
//   原因：v25 要求开录前首 4 字节必须为 0xFF（"已擦除"），只要 BDT 擦除后该处
//         不是 0xFF（全 0 或残留旧数据），就判 FC_BB_ST_FULL，从此一条不录，
//         BDT 抽查自然只见 0；且 v25 的 bb_state 上电默认 IDLE，不做任何区域
//         准备，用户无从得知为什么没录。
//   方案：上电即进入"区域准备"(FC_BB_ST_PREP)，按 FC_BB_AUTO_ERASE 自愈：
//         首 4B 全 FF → 直接写区域头；
//         否则（全 0 或旧数据）→ 固件擦除整个录制区再写头。★ 只在停转 /
//         遥控已连 / 未打摇杆组合时推进，每 FC_BB_ERASE_GAP 擦 1 扇区，
//         单次丢包 <10 个，远低于 u32NoRxdCnt>100 的清解锁阈值 → 不会重演
//         v20/v21 的"擦除致失联"（那两版无法解锁的真因已查明是 RAM 溢出）。
//         写头后立即回读校验，结果写入 FlightCtrl_BBDiag，BDT 可直接观察。
//   录制起点改为"真正起飞后"（FC_ST_TAKEOFF / FC_ST_FLY）：解锁到推油门前的
//         地面等待不再占容量，也不会把地面静止数据当成飞行数据。
// 存储布局：0x10000 +0 16B 区域头：A5 5A BB BB | ver | rec_size(2B BE) | div | 保留
//   +16..  每条 38B：17×s16(大端) + seq u16 + flags u8 + reason u8（同 v20）
//          ★v27 flags 位定义（旧版只有 bit0~2，且 DISARM 直接 stop 不写记录，
//          导致 reason/flags 两个字段从来没记录过真实信息）：
//            bit0 本拍仍解锁   bit1 已离地      bit2 离地静默窗内
//            bit3 低压关机位   bit4 失联(link_ok=0 或 1S 无数据)
//            bit5 触地判定窗口内              bit6 收尾记录(上锁当拍补写)
//          上锁那一拍会额外补写一条 bit6=1 的记录 → 末条 reason 即停机原因。
//   容量 64KB ≈ 1731 条 × 50Hz ≈ 34.6S 飞行记录。
// 读出：落地上锁后按遥控器【特技表演】键 → UART 输出 → parse_fcbb.py 解析。
//----------------------------------------------------------------------------------
// ---- 配置 ----
#define FC_BB_BASE			0x10000		// 录制区首地址（与代码区无冲突：LMA 上限 <0x9000）
#define FC_BB_SIZE			0x10000		// 64KB → 0x10000~0x1FFFF
#define FC_BB_REC_SIZE		42			// 每条记录字节数（parse_fcbb.py 按此解析；v34 由 38 扩 2×s16 陀螺）
#define FC_BB_REC_DIV		4			// 每 4 拍(20mS)记 1 条 = 50Hz（容量 64KB/42B ≈ 31.2S）
#define FC_BB_CHUNK			32			// UART 读出块大小（≤UART_DATA_LEN-4）
#define FC_BB_AUTO_ERASE	1			// 1: 上电后录制区非空白则自动擦除（安全条件见上）
										// 0: 只认 BDT 擦除，未擦则 BBState=3(FULL)
#define FC_BB_ERASE_GAP		40			// 每 40 拍(200mS)擦 1 扇区（限速，防失联）
// 黑匣子状态（FlightCtrl_BBState 观察用）
#define FC_BB_ST_IDLE		0			// 就绪，等起飞（上锁后回到此态）
#define FC_BB_ST_REC		1			// 录制中（已起飞）
#define FC_BB_ST_DUMP		2			// UART 读出中（特技键触发）
#define FC_BB_ST_FULL		3			// 容量满 / 区域不可用
#define FC_BB_ST_PREP		4			// 区域准备中（擦除+写头，上电默认）

//----------------------------------------------------------------------------------

//==================================================================================
// 8、起飞 / 降落 / 保护
//==================================================================================
//----------------------------------------------------------------------------------
// 一键起飞：以固定起降速度原地垂直升高约 2 米，然后进入悬停
// 	起降速度 19.2cm/S = 192 (0.1cm/S 单位)。
// 	★ 2026/11/04 注：油门满杆降为 12cm/S 后，该速度不再与"20% 油门"挂钩，
// 	  改为固定绝对速度（一键起降的爬升/下降节奏保持原样，便于对比测试）。
// 	2 米 = 200cm = 2000 (0.1cm 单位)
//----------------------------------------------------------------------------------
#define FC_AUTO_VZ_X10		192			// 起降速度 19.2cm/S（固定值，不随油门量程变化）
#define FC_TAKEOFF_ALT_X10	2000		// 一键起飞目标高度 2 米（0.1cm 单位）
#define FC_TAKEOFF_VZ		(FC_AUTO_VZ_X10)	// 起飞爬升速度 19.2cm/S
#define FC_LANDING_VZ		(-(FC_AUTO_VZ_X10))	// 降落下降速度 -19.2cm/S
// 目标高度量程限制（0.1cm 单位）。允许为负，只防跑飞：
// ★ v34 下限 -20m→-10cm。V32_2/V33_1 两场坠机实录：油门杆下拉时目标高度以
//	~8cm/S 滑到 -5.2/-7.1cm（地面以下），高度环忠实执行"降到地面以下"→ 贴地
//	湍流中翻机/顶墙。-10cm 保留"桌面起飞→地面降落"能力，同时堵死目标钻地。
//	上限 10m 防止目标无限累积，不变。
#define FC_ALT_TARGET_MIN_X10	(-100)
#define FC_ALT_TARGET_MAX_X10	(10000)

// 上升 200cm / 19.2cm/S ≈ 10.4S，故超时保护要留足余量
#define FC_TAKEOFF_TMOUT	3000		// 起飞超时保护 3000×5mS = 15S
#define FC_LANDING_TMOUT	3000		// 降落超时保护 3000×5mS = 15S

#define FC_TILT_LIMIT		5000		// 翻机保护倾角 50.00°(0.01°单位)
#define FC_ARM_TILT_LIMIT	1500		// 解锁允许的最大倾角 15.00°
#define FC_LAND_STICK_REL	1			// 1: 一键降落要求四个摇杆全部回中

// 落地/结束飞行判据 ★ v19 按用户判定重写：
//	【拉杆要求下降，但连续 3S 评估高度几乎没变】→ 已落住 → 上锁、关全部马达。
//	★ 删除旧判据里的"目标低于实际 6cm"条件（FC_GROUND_ERR_X10 已删）——
//	目标高度允许为负（低于起飞点），目标低只代表要求的高度低，不代表着地。
//	窗口内降幅门槛 3cm 的安全性：杆指令最小下降为 2cm/S（死区 1 的下一档），
//	3S 降 6cm，远大于 3cm；真落住时降幅≈0（中值滤波后漂移 ~1cm/3S），不误判。
#define FC_GROUND_MIN_DROP	30			// 3S 窗口内实际高度下降不足 3.0cm → 判定已落住
#define FC_GROUND_TMOUT		600			// 窗口长度 600×5mS = 3S（v19 由 1S 加长，用户要求）
#define FC_GROUND_REQ_TMOUT	600			// 拉过下降杆后 600×5mS = 3S 内允许做落地判定
										// （松杆后仍能完成判定，但气压漂移不会单独触发）

//==================================================================================
// 7.1 离地 / 触地检测（2026/11/03 新增，解决"桨流污染气压 → 高度环失控"）
//----------------------------------------------------------------------------------
// BDT 实测（压在地上推油门）：AltX10 = -54.6cm！物理上在起飞点却读出 -54.6cm。
//	原因：桨的下洗气流打在气压计上，推力越大/越贴近地面，气压读数越高，
//	高度估计被压得越低 → 高度环误以为没爬够 → 油门推到饱和(400) → 桨流更强
//	→ 恶性正反馈，这就是"不悬停、一直斜线上升"的根源。
// 对策：
//	① 离地前（!airborne）：高度环不参与，推力按斜坡上升强制起飞；
//	   目标高度冻结为 0、速度环积分钉在悬停值 → 地面阶段不产生任何误差债务；
//	② 离地瞬间重新清零高度基准（SetAltRef），把地面阶段的桨流污染一次性甩掉；
//	③ 气压滤波：★ v19 改为 5 点中值滤波（FC_PRES_MED_N，用户建议与其六轴
//	  PushRfDatToFIFO 同款：初始化一次性填满 FIFO）——中值对 I2C 坏点/毛刺
//	  天然免疫（5 个样本混入 1~2 个坏点不影响输出），取代旧的"野点剔除+
//	  一阶低通"两级处理；FC_PRES_GLITCH 仅保留为 PresDrop 统计计数。
//==================================================================================
// ★ 2026/11/03 台架实测（BDT 抓图）：压住飞机推油门时 Airborne=1 —— 离地检测误触发。
//	原因：原判据阈值 25cm/S² 太低、只要求持续 50mS，满推力振动/手压晃动即可满足；
//	气压法备用判据（est>10cm 且 vz>15cm/S）在地面阶段同样被桨流污染，一并删除。
//	现只保留加速度判据为主，且阈值/持续时间都加严——真正的离地推力斜坡会越过悬停点，
//	a_vert 会持续远超 50cm/S²，不会漏判；漏判兜底是触地检测 + 3S 地面超时上锁。
//	★v28 辅助判据回归：v27_1 实录显示 a_vert 振动凹陷会把计数清零、离地确认拖到推力
//	338（过推 88PWM，混控差动余量被挤干 → 姿态发散翻机）。加气压正速度 OR 判据——
//	桨流只会造成"假下降"，绝不会造成"假爬升"，vz_baro 持续为正是非常可靠的离地信号。
#define FC_LIFTOFF_ACC		800			// 垂向加速度低通值 > 80cm/S²（推力已明显超过重力）
										//   ★v29 50→80：V28_1 实录地面斜坡振动就能让
										//   a_vert 过 50 连满 100mS → 假离地
#define FC_LIFTOFF_THR_MIN	(FC_PWM_HOVER-25)	// ★v29 a_vert 判据的推力门限 = 225。
										//   推力低于悬停值物理上不可能离地；V28_1 在
										//   推力仅 218 时就被振动判成离地，连锁伤害
										//   是静默窗学到假悬停 208（低 42PWM）。
										//   a_vert 计数仅在 thrust_last ≥ 此值时进行；
										//   气压正速度判据不受此门限限制（假下降只
										//   会压低 vz_baro，不会假抬升）
#define FC_LIFTOFF_CNT		20			// 持续 20×5mS = 100mS 确认离地（★v28 200→100mS 提速，
										//   v27_1 实测 200mS 期间被振动凹陷清零、确认滞后
										//   0.18S → 过推；100mS 内即没被真离地满足，后面
										//   还有气压判据与 3S 地面超时兜底，风险可控）
#define FC_LIFTOFF_BARO_VZ	200			// ★v28 辅助判据：气压升降速度 > +20cm/S（0.1cm/S）
#define FC_LIFTOFF_BARO_CNT	20			//   持续 20×5mS = 100mS → 也确认离地（与 a_vert 判据 OR）
#define FC_GND_RAMP_CAP		(FC_PWM_HOVER+40)	// ★v28 地面斜坡/起飞推力封顶 = 290。
										//   v27_1 实录：斜坡一路推到 338，差动余量
										//   min(160, t-51, 392-t) 只剩 54~68（设计 160），
										//   姿态环拉不住固定偏置力矩 → 俯仰发散翻机。
										//   290 留 102 余量；若 290 离不了地说明悬停
										//   标定有误，走地面超时上锁更安全
#define FC_GND_RAMP_TMOUT	600			// 地面阶段最长 600×5mS = 3S，仍离不了地 → 上锁
#define FC_PRES_GLITCH		80			// 气压毛刺统计阈值：中值输出与上拍差 >8cm
										// 计入 PresDrop（仅统计观察用，v19 起不再丢样本）

//----------------------------------------------------------------------------------
// ★ 2026/11/03 气压计三段实测结论（固定支架、64Hz、200counts=1cm）：
//	① 马达一转，气压读数阶跃 +1412 counts = 表观高度 -7.1cm，停桨瞬间恢复——
//	  是桨流（动压/下洗）偏置，不是温度漂移（温度漂移不可能 0.2S 内消失）；
//	② 贴地时该偏置更大（早前 BDT 实测满推力 -54.6cm），即地面效应加剧；
//	③ 静止噪声 σ=0.45cm/样本、峰峰 2.9cm；马达运转时噪声 +30%；
//	④ 几分钟内热漂移约 2.9cm。
//	推论：离地瞬间推力在最大值附近，此刻清气压基准会把"最大桨流偏置"当零点；
//	随后高度环把推力压回悬停值，偏置回落 → 估计跳回十几厘米 → 高度环再动作
//	→ 反复"快定高又上飞"（6~7 次脉冲）。对策 = 离地静默窗口（见下）。
//----------------------------------------------------------------------------------
// ★ v19（按用户判定重写窗口行为，取消 v18 冻结推力做法）：窗口内改用
//	【加计积分速度 + 垂直速度PID】主动把起飞初始爬升刹住（目标 0，见
//	FlightCtrl.c ⑦），而不是被动冻结推力；窗口结束时重清气压基准 +
//	学习悬停油门，切换到气压单环高度PID。窗口时长保持 2S：既让桨流偏置
//	稳定（重清基准才可靠），也给加计速度环足够收敛时间。
// ★ 2026/11/10 v20（第20轮 v19 实测"起飞即侧翻"的三保险，用户批准 1+2+3）：
//	v19 静默窗内 vz_acc 被振动整流灌到 +30cm/s 饱和 → PID 误判"狂爬"全力刹车
//	→ 2S 内推力坍缩到 ≈80 → 低空坠地侧翻（根因链见 2026/11/10 日志）。三保险：
//	  ① 泄漏式 vz_acc：积分器每拍向零衰减（τ≈0.64S），真实加速度瞬态仍能刹车，
//	    整流偏置无法积累成假速度（稳态假速度 = 偏置×τ，有界且随偏置减小）；
//	  ② 静默窗推力下限 = 悬停油门 − FC_QUIET_THR_FLOOR：任何误判都不允许
//	    推力坍缩坠地（v19 实测坍缩到 80PWM 的直接保护）；
//	  ③ 窗口 2S→0.6S + 窗内积分钳位到悬停 ±FC_QUIET_I_BAND：缩短暴露时间，
//	    且积分不会在误判中深灌（窗末学习悬停油门时不带大偏差）。
#define FC_LIFT_QUIET		120			// 离地静默窗口 120×5mS = 0.6S（v20 由 2S 缩短）

// ★v20 三保险参数（见 FC_LIFT_QUIET 注释）
// ★v27：地板/钳位带的基准由"标定悬停油门"改为【离地当拍的实测推力】
//	（FlightCtrl.c 里 liftoff_thrust）——标定值再怎么调也追不上电池电压、
//	桨况、起飞重量的变化，而"这一架次用什么推力离的地"是现场真值。
#define FC_VZ_ACC_LEAK_SHIFT	7		// vz_acc 泄漏 >>7/拍，τ = 128拍×5mS ≈ 0.64S
#define FC_QUIET_THR_FLOOR	20			// 静默窗推力下限 = 离地推力 − 20 PWM
										//   v27: 30→20（v26 实测离地推力≈250，地板
										//   从 140 提到 230，杜绝"离地即掉回地面"）
#define FC_QUIET_I_BAND		20			// 静默窗内积分钳位带：离地推力 ±20 PWM

// 触顶/堵转检测（已离地后的"升不上去/被压住"判据，补 FC_GROUND_* 的反向漏洞）
//	★ v19 按用户指正更名：旧称"触地判定"，但其条件【要求爬升却升不上去】
//	语义上是"被压住/堵转"（手按住、顶到天花板、或落地后被桨流压低估计）——
//	与"拉杆降不下去"（落地判定）方向相反、互为补充。
//	v19 判据（单环架构，无 vz_cmd，改为用高度误差表达"要求爬升"）：
//	  ① 目标高于估计 FC_TDCD_ALTERR(10cm) 以上 = 正在要求爬升；
//	  ② 垂向加速度≈0（并没有在加速）；
//	  ③ FC_TDCD_WIN=2S 窗口内高度估计涨幅 < FC_TDCD_MIN_RISE=10cm。
//	三条同时成立 → 判定被压住 → 结束飞行。
//	★ 用"窗口涨幅"而不是瞬时速度：气压滞后/桨流偏置时瞬时值不可信（真机
//	  2026/11/03 实证：松杆后一级一级往上飞 6~7 次后马达停掉，就是旧瞬时判据误杀）。
//	没有它的话：落地后 est 被桨流压得比目标还低，高度环一直以为没到目标高度，
//	马达会在地面上满油门空转、永远停不下来（BDT 抓图实证）。
#define FC_TDCD_ALTERR		100			// 目标高于估计 10cm 以上 = 要求爬升（v19 替代 FC_TDCD_VZCMD）
#define FC_TDCD_CNT			300			// 持续 300×5mS = 1.5S → 判定（计数为衰减式，见 .c）
#define FC_TDCD_ARM_DLY		400			// 离地后 400×5mS = 2S 内禁止触地判定——
										// 起飞瞬间推力大起大落，桨流偏置来回跳，
										// 早判容易把"正常起飞过渡"误判成触地（空中停桨）
// ★ 2026/11/03 真机实测：判据改为「2S 窗口内高度估计涨幅 < 10cm」才停桨——
//	原来只看 vz_est<10cm/S 会误杀（气压滞后/桨流偏置时飞机明明在爬，vz_est
//	却是小的），空中停桨非常危险。窗口判据和"降不下去"判据同构，抗滞后。
#define FC_TDCD_WIN			400			// 判定窗口 400×5mS = 2S
#define FC_TDCD_MIN_RISE	100			// 窗口内 est 涨幅 < 10cm → 认定"没升起来"

//==================================================================================
// 7.2 高度估计平滑（v19：一阶低通已删除，由 5 点中值滤波取代，见 7.1 ③）
//----------------------------------------------------------------------------------
// 实测现象（历史）：松杆后飞机反复「快定高→又上飞一小段」——alt_est 直接用
//	单次气压换算值时，噪声/桨流偏置 ±3cm 量级地跳，高度环立刻翻译成速度指令。
//	旧对策一阶低通(τ125mS)有效但引入相位滞后；v19 中值滤波既压毛刺又对缓变
//	信号零滞后（中值≈均值），高度环拿到的是"干净且不滞后"的高度。
//==================================================================================
#define FC_PRES_MED_N		5			// 气压中值滤波 FIFO 长度（用户建议，同其六轴滤波）

//==================================================================================
// 7.3 「松杆抓高度」的基准重清（★解决"一级一级往上飞"的关键）
//----------------------------------------------------------------------------------
// 桨流把气压计压低几十厘米这件事，离地瞬间还没建立完：起飞后 0.5~2S 里偏置
// 才慢慢长到稳态值。于是高度估计一路往下掉 → 高度环以为"还差很多" → 往上
// 爬一段 → 爬高后偏置又变小 → est 回升 → 停一下 → 偏置重新建立 → 再爬…
// 表现就是"快定高了又上飞一小段"，反复 N 次。
// 对策：玩家第一次把油门杆松到死区内（= 想在此定高）时，把高度基准重清一次：
//	est=0、目标=0、vz=0 —— 把此刻的稳态桨流偏置一并甩掉，之后就以"松杆点"
//	为零点定高。之后再推/拉杆，目标高度从这个新零点开始积分。
//==================================================================================
#define FC_HOVER_REF_EN		1			// 1: 启用松杆重清基准
#define FC_HOVER_REF_DLY	200			// 离地至少 200×5mS = 1S 后才允许重清

// 推力指令上限（调试旋钮）：默认 = FC_PWM_MAX。若怀疑"爬升时油门顶到 400
// 导致混控失去差动余量 → 左右摇晃"，把它改小（如 340~360）试一次：
//	基础油门一旦顶到上限，四轴就没有加减速的余量，姿态环等于开环。
//	★v28: 340→290（=FC_GND_RAMP_CAP）。v27_1 实录推力 324 时差动余量只剩 68
//	（设计 160 的 42%），out_p 贴 ±150 也拉不住俯仰固定偏置 → 28°/S 匀速发散
//	到翻机保护。与地面斜坡封顶保持一致，飞行中恢复推力同样不超过它。
#define FC_THR_MAX_CMD		(FC_PWM_HOVER+40)

#define FC_HEADLESS_EN		0			// 1: 启用无头模式（需先确认 Yaw 不漂移太快）

// 推油门起飞：已解锁 + 未起飞状态下，油门上推超过 FC_THR_START_THR 即直接起飞，
// 不必按一键起降键（起飞后油门杆恢复"控制升降速度"的常态功能）
// ★ 2026/11/04 油门满量程 96→12，触发阈值按同比例（约 1/5 行程）从 20 缩到 2，
//   否则油门推到头也只有 12cm/S，永远触不了发。
#define FC_THR_START_EN		1			// 1: 启用推油门起飞
#define FC_THR_START_THR	2			// 油门 > 2cm/S（约 1/6 行程）触发起飞

//==================================================================================
// 9、对外接口
//==================================================================================
// 上电初始化（清状态、装载增益、设定高度零点）
void FlightCtrl_Init(void);
// 复位：清空积分、状态机回到上锁（不改变气压基准）
void FlightCtrl_Reset(void);
// 以当前气压值为高度零点（起飞前/重新定高前调用）
void FlightCtrl_SetAltRef(void);
// 控制节拍：由主循环每 FC_CTRL_DT_MS 调用一次
// 内部完成：读陀螺仪 → 姿态解算 → 姿态/高度/偏航控制 → 混控 → 更新4路马达PWM
void FlightCtrl_Tick(void);
// 供调试观察的变量（飞控内部状态都是 static，靠这几个全局变量镜像出来给外部看）
extern u8	FlightCtrl_State;		// 飞行状态机 0:上锁 1:起飞爬升 2:飞行(定高) 3:降落
extern u8	FlightCtrl_Unlocked;	// 解锁标志 0:锁定(不能起飞) 1:已解锁
extern u8	FlightCtrl_CalState;	// 水平校准 0:空闲 1:采样中 2:完成
extern u8	FlightCtrl_Stunt;		// 特技表演 0:未进行 1:顺时针盘旋中
extern u16	FlightCtrl_DescBlock;	// 落地判定计时(0~FC_GROUND_TMOUT)，到 600(3S) 即上锁
extern u8	FlightCtrl_Airborne;	// 0:未离地(地面阶段) 1:已离地
extern s16	FlightCtrl_AVert;		// 垂向加速度低通值【已扣零偏】(0.1cm/S²，静止≈0，离地为正)
extern s16	FlightCtrl_AccBiasX10;	// 垂向加速度零偏学习值(0.1cm/S²)：解锁前看它是否收敛
extern s16	FlightCtrl_OutRoll;		// 滚转控制输出(PWM)
extern s16	FlightCtrl_OutPitch;	// 俯仰控制输出(PWM)
extern s16	FlightCtrl_OutYaw;		// 偏航控制输出(PWM)
extern s16	FlightCtrl_Thrust;		// 基础油门(PWM)
extern s16	FlightCtrl_AltX10;		// 当前高度估计(0.1cm)
extern s16	FlightCtrl_VzX10;		// 当前升降速度估计(0.1cm/S)，融合值
extern s16	FlightCtrl_VzBaroX10;	// 气压慢通道升降速度(0.1cm/S)，与 VzX10 对比看融合效果
extern s16	FlightCtrl_HTrimR01;	// 悬停漂移自学习配平 roll(0.01°)：悬停中应缓慢趋向稳定值
extern s16	FlightCtrl_HTrimP01;	// 悬停漂移自学习配平 pitch(0.01°)：同上；漂移加剧则关 FC_HTRIM_EN
//---- 2026/11/04 第三轮新增：垂直链路三段全暴露，飞行中一眼看出卡在哪 ----
extern s16	FlightCtrl_VzAccX10;	// 加计快通道速度(0.1cm/S)：静止/匀速应≈真实速度，
									// 与 VzX10 差值 = 气压纠漂量；与 VzBaroX10 差值 = 桨流污染量
extern s16	FlightCtrl_VzCmdX10;	// 油门杆指令升降速度(0.1cm/S，遥测显示；v19 单环后不再参与控制)
extern s16	FlightCtrl_AltErrX10;	// 高度误差 目标-估计(0.1cm)，已过死区
extern s32	FlightCtrl_AltTargetX10;// 目标高度(0.1cm)
//---- 气压计健康度（2026/11/03 新增：飞行中抓气压实时数据用）----
extern s32	FlightCtrl_PresRaw;		// 气压计原始计数 s32PresValue（每升高1cm约 -200）
extern s16	FlightCtrl_PresAltX10;	// 本拍未滤波、未剔除的高度换算值(0.1cm)，与 AltX10 对比可见噪声/跳点
extern u16	FlightCtrl_PresCnt;		// 气压采样计数（每来一拍 +1；不动 = I2C 掉/被阻塞）
extern u16	FlightCtrl_PresDrop;	// 野点丢弃计数（涨得快 = 气压读数在乱跳）
//---- 停桨原因（飞行中突然停桨时看它，避免瞎猜）----
extern u8	FlightCtrl_DisarmReason;// 0无 1失联 2低压 3翻机(倾角>50°) 4地面超时(3S起不来)
									// 5触顶/堵转(要求爬升却升不上去,v19更名) 6已落住(拉杆降不下,v19重写)
									// 7一键降落落地 8一键降落超时
extern s16	FlightCtrl_DisarmAltX10;// 停桨瞬间的高度估计(0.1cm)
extern s16	FlightCtrl_DisarmTilt;	// 停桨瞬间的倾角 max(|roll|,|pitch|)，单位 0.01°
//---- ★v23 解锁诊断镜（排查 v20~v22 无法解锁，BDT 直接观察）----
extern u16	FlightCtrl_TickCnt;		// 每节拍+1：不动 = 5mS 节拍死了
extern u8	FlightCtrl_ComboType;	// 组合实时值 0无 1解锁 2校准
extern u16	FlightCtrl_ComboHold;	// 组合保持计数(×5mS)，100=解锁门限
extern u16	FlightCtrl_NoRxdPeak;	// u32NoRxdCnt 开机以来峰值（>100 = 发生过假失联清解锁）
//---- ★v26 flash 黑匣子（FlightCtrl.h 7.11）----
extern u8	FlightCtrl_BBState;		// 0就绪 1录制中 2读出中 3满/不可用 4区域准备中
extern u16	FlightCtrl_BBRecs;		// 已录制条数（×20mS = 录制时长）
extern u32	FlightCtrl_BBWRAddr;	// 下一条记录写入地址（诊断：是否随飞行增长）
// 区域准备自检（★v26：BDT 直接读这几个 RAM 变量即可判断录不上的原因）
extern u8	FlightCtrl_BBDiag;		// bit0 上电检测到非空白  bit1 擦除后回读全FF
									// bit2 写头后回读匹配(A5..BB)  bit3 写头后回读不匹配
									// bit4 flash 容量 <128KB（录制区越界）
extern u8	FlightCtrl_BBChk0;		// 准备前 0x10000 首字节（0xFF=已擦 0x00=全零）
extern u8	FlightCtrl_BBChk1;		// 擦除后 0x10000 首字节（应 0xFF）
extern u8	FlightCtrl_BBChk2;		// 写头后 0x10000 首字节（应 0xA5）
extern u8	FlightCtrl_BBChk3;		// 写头后 0x10000 第 4 字节（应 0xBB）
extern u8	FlightCtrl_BBFlashCap;	// flash 容量码（0x10=64K 0x11=128K 0x12=256K 0x13=512K 0x14=1M）

// flash 黑匣子：上电初始化（进入区域准备态）+ 读出触发（特技键，仅停转生效）
void BlackBox_Init(void);
void BlackBox_DumpStart(void);

// 查询：四个摇杆是否全部处于释放（回中）状态
u8 FlightCtrl_AllStickReleased(void);

